'use strict';
// ================================================================== the proposal: the spec (v2, 25 Oct 2026)
function R(key, label, kind, o) { return Object.assign({ id: key, key, label, kind, help: '', needs: 'live', tier: 'player', parent: null }, o || {}); }
const T = (key, label, def, o) => R(key, label, 'toggle', Object.assign({ def, value: def }, o));
const P = (key, label, options, def, o) => R(key, label, 'picker', Object.assign({ options, def, value: def }, o));
const S = (key, label, min, max, step, def, o) => R(key, label, 'slider', Object.assign({ min, max, step, def, value: def, unit: '', words: [] }, o));
const K = (key, label, def, o) => R(key, label, 'key', Object.assign({ def, value: def }, o));
const B = (key, label, o) => R(key, label, 'button', Object.assign({ def: null, value: null }, o));

