// ================================================================== glyphs: three families over one positional layout
// Logical inputs are Xbox-positional (A = south, B = east, X = west, Y = north). Switch labels the same positions B / A / Y / X.
const INPUTS = ['LS', 'RS', 'L3', 'R3', 'LT', 'RT', 'LB', 'RB', 'A', 'B', 'X', 'Y', 'DU', 'DD', 'DL', 'DR', 'VIEW', 'MENU'];
const GLYPHSETS = {
  xbox: { name: 'Xbox', A: ['A', '#7ac142'], B: ['B', '#e4404a'], X: ['X', '#2f8fdc'], Y: ['Y', '#f7d000'], LB: 'LB', RB: 'RB', LT: 'LT', RT: 'RT', L3: 'L', R3: 'R', LS: 'L', RS: 'R', VIEW: 'VIEW', MENU: 'MENU', DU: '▲', DD: '▼', DL: '◀', DR: '▶' },
  ps: { name: 'PlayStation', A: ['✕', '#8ab5e6'], B: ['○', '#e76d6d'], X: ['□', '#e37fb0'], Y: ['△', '#7bc77e'], LB: 'L1', RB: 'R1', LT: 'L2', RT: 'R2', L3: 'L3', R3: 'R3', LS: 'L', RS: 'R', VIEW: 'CREATE', MENU: 'OPTIONS', DU: '▲', DD: '▼', DL: '◀', DR: '▶' },
  switch: { name: 'Switch', A: ['B', '#ffffff'], B: ['A', '#ffffff'], X: ['Y', '#ffffff'], Y: ['X', '#ffffff'], LB: 'L', RB: 'R', LT: 'ZL', RT: 'ZR', L3: 'L', R3: 'R', LS: 'L', RS: 'R', VIEW: '−', MENU: '+', DU: '▲', DD: '▼', DL: '◀', DR: '▶' }
};
const KM = { A: 'ENTER', B: 'ESC', X: 'DEL', Y: 'TAB', LB: 'Q', RB: 'E', LT: 'PGUP', RT: 'PGDN', L3: 'HOME', R3: 'END', LS: 'WASD', RS: 'MOUSE', VIEW: 'F6', MENU: 'F1', DU: '↑', DD: '↓', DL: '←', DR: '→' };
function glyph(input, set) {
  const s = GLYPHSETS[set] || GLYPHSETS.xbox; const v = s[input];
  if (set === 'km') return `<span class="g km">${esc(KM[input] || input)}</span>`;
  if (['A', 'B', 'X', 'Y'].includes(input)) return `<span class="g face" style="color:${v[1]};border-color:${v[1]}">${v[0]}</span>`;
  if (['LB', 'RB', 'LT', 'RT'].includes(input)) return `<span class="g sh">${esc(v)}</span>`;
  if (['L3', 'R3'].includes(input)) return `<span class="g stick" title="press the stick">${esc(v)}</span>`;
  if (['LS', 'RS'].includes(input)) return `<span class="g stick">${esc(v)}</span>`;
  if (['DU', 'DD', 'DL', 'DR'].includes(input)) return `<span class="g dpad">${esc(v)}</span>`;
  if (['VIEW', 'MENU'].includes(input)) return `<span class="g sys">${esc(v)}</span>`;
  return `<span class="g sys">${esc(input)}</span>`;
}
function glyphName(input, set) { const s = GLYPHSETS[set] || GLYPHSETS.xbox; const v = s[input]; return Array.isArray(v) ? v[0] : v; }

